import{_ as e,c as t,o as r,a3 as o}from"./chunks/framework.BusRvirq.js";const p=JSON.parse('{"title":"엔지니어링 연구 아카이브 (Study)","description":"SyncSeries 핵심 기술 스택인 Playwright, Vision-LLM, MCP, 하이브리드 RAG, 고성능 Java 런타임에 대한 심층 기술 연구 및 아키텍처 분석 자료집입니다.","frontmatter":{"title":"엔지니어링 연구 아카이브 (Study)","description":"SyncSeries 핵심 기술 스택인 Playwright, Vision-LLM, MCP, 하이브리드 RAG, 고성능 Java 런타임에 대한 심층 기술 연구 및 아키텍처 분석 자료집입니다.","head":[["meta",{"name":"keywords","content":"기술연구, Playwright CDP, Vision-LLM, 자가치유 알고리즘, MCP 오케스트레이션, 하이브리드 RAG, 가상 스레드, AgentScope, 엠파시"}],["meta",{"property":"og:title","content":"엔지니어링 연구 아카이브 | 엠파시(Empasy)"}],["meta",{"property":"og:description","content":"실전 엔지니어링 문제 해결을 위한 심층 기술 분석 및 아키텍처 연구 자료입니다."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/study/"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/study/"}]],"sort":1},"headers":[],"relativePath":"study/index.md","filePath":"ko/study/index.md","lastUpdated":1789483631000}'),n={name:"study/index.md"};function i(s,a,l,h,d,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="엔지니어링-연구-아카이브-study" tabindex="-1">엔지니어링 연구 아카이브 (Study) <a class="header-anchor" href="#엔지니어링-연구-아카이브-study" aria-label="Permalink to “엔지니어링 연구 아카이브 (Study)”">​</a></h1><p>본 공간은 엠파시 SyncSeries(SyncEta, SyncVerse, SyncBoot, SyncCrawl 등) 제품군의 기반이 되는 핵심 기술 스택에 대해, 구현 원리와 성능 벤치마크, 아키텍처 설계 패턴을 심층 연구하여 기록하는 기술 아카이브입니다.</p><hr><h2 id="핵심-연구-주제-분류" tabindex="-1">핵심 연구 주제 분류 <a class="header-anchor" href="#핵심-연구-주제-분류" aria-label="Permalink to “핵심 연구 주제 분류”">​</a></h2><h3 id="_1-웹-브라우저-자동화-qa-엔지니어링" tabindex="-1">1. 웹 브라우저 자동화 &amp; QA 엔지니어링 <a class="header-anchor" href="#_1-웹-브라우저-자동화-qa-엔지니어링" aria-label="Permalink to “1. 웹 브라우저 자동화 &amp; QA 엔지니어링”">​</a></h3><ul><li><strong><a href="./playwright-cdp-visual-regression">Playwright 및 CDP 기반 시각적 회귀 분석과 DOM 동기화</a></strong>: Chrome DevTools Protocol을 활용한 렌더링 프레임 캡처 및 네트워크 유휴 상태 동기화 기법 분석.</li><li><strong><a href="./vision-llm-self-healing-algorithm">Vision-LLM 기반 UI 요소 바운딩 박스 추론 및 자가 치유(Self-Healing) 알고리즘</a></strong>: 화면 시각적 문맥과 좌표를 활용하여 클래스명 변경에 대응하는 회귀 테스트 복구 파이프라인.</li></ul><h3 id="_2-분산-에이전트-프로토콜" tabindex="-1">2. 분산 에이전트 &amp; 프로토콜 <a class="header-anchor" href="#_2-분산-에이전트-프로토콜" aria-label="Permalink to “2. 분산 에이전트 &amp; 프로토콜”">​</a></h3><ul><li><strong><a href="./mcp-jsonrpc-agent-orchestration">Model Context Protocol(MCP) JSON-RPC 사양 분석과 도구 오케스트레이션</a></strong>: Claude/Playwright 표준 도구 인터페이스와 엔터프라이즈 보안 게이트웨이 설계 패턴.</li><li><strong><a href="./springboot-virtual-threads-agentscope">Java 21 가상 스레드와 AgentScope 기반 비동기 메시징 성능 분석</a></strong>: Spring Boot 환경에서 블로킹 I/O 극복과 수만 단위 동시 에이전트 통신 처리 벤치마크.</li></ul><h3 id="_3-ai-모델-지식-파이프라인" tabindex="-1">3. AI 모델 &amp; 지식 파이프라인 <a class="header-anchor" href="#_3-ai-모델-지식-파이프라인" aria-label="Permalink to “3. AI 모델 &amp; 지식 파이프라인”">​</a></h3><ul><li><strong><a href="./hybrid-rag-dense-sparse-reranking">엔터프라이즈 RAG 아키텍처: Sparse + Dense 하이브리드 검색과 Cross-Encoder 리랭킹</a></strong>: 도메인 특화 검색 정밀도 향상을 위한 BM25와 임베딩 벡터 결합 파이프라인.</li><li><strong><a href="./qwen2vlfinetuning">Qwen2-VL 멀티모달 모델 파인튜닝 실무</a></strong>: 한국어 웹 UI 화면 컴포넌트 인식을 위한 데이터셋 구성 및 LoRA 튜닝.</li><li><strong><a href="./LLM 파인튜닝 후 성능 저하 원인 및 해결책 분석">LLM 파인튜닝 후 성능 저하 원인 및 해결책 분석</a></strong>: Catastrophic Forgetting 방지 및 정렬 데이터 보정 연구.</li><li><strong><a href="./rag">RAG 기반 지식 검색 파이프라인 구축</a></strong>: 비정형 데이터 청킹 및 메타데이터 필터링 전략.</li></ul><hr><h2 id="연구-방법론-및-검증-기준" tabindex="-1">연구 방법론 및 검증 기준 <a class="header-anchor" href="#연구-방법론-및-검증-기준" aria-label="Permalink to “연구 방법론 및 검증 기준”">​</a></h2><p>엠파시 엔지니어링 팀은 모든 기술 연구에서 다음 원칙을 준수합니다:</p><ol><li><strong>코드 레벨 실증</strong>: 이론적 모델에 그치지 않고 실제 실행 가능한 프로토타입 또는 벤치마크 코드를 작성하여 성능을 검증합니다.</li><li><strong>정량적 데이터 제시</strong>: 레이턴시, 메모리 점유율, 처리량(Throughput), 실패율 등 수치화된 지표를 기반으로 기술 채택 여부를 결정합니다.</li><li><strong>상용 안정성 검토</strong>: 네트워크 단절, 스레드 고갈, DOM 지연 렌더링 등 에지 케이스에 대한 방어 로직을 포함합니다.</li></ol>',14)])])}const m=e(n,[["render",i]]);export{p as __pageData,m as default};
